<?php require __DIR__.'/../includes/bootstrap.php';require_admin();if(!events_schema_ready())redirect('upgrade-events.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='status'){db()->prepare('UPDATE events SET status=?,is_featured=? WHERE id=?')->execute([$_POST['status'],isset($_POST['is_featured'])?1:0,(int)$_POST['event_id']]);flash('success','Event updated.');}elseif($action==='demo'){try{$users=db()->query("SELECT id FROM users ORDER BY id LIMIT 6")->fetchAll(PDO::FETCH_COLUMN);if(!$users)throw new RuntimeException('Create users before generating demo events.');$types=array_keys(event_type_options());for($i=0;$i<6;$i++){$title=['Multiverse Creator Panel','Cosplay Armor Workshop','Collector Trade Night','Indie Game Tournament','Artist Signing Hour','Geek Nation Live Q&A'][$i].' '.substr(bin2hex(random_bytes(3)),0,6);$start=date('Y-m-d H:i:s',strtotime('+'.($i+2).' days +'.$i.' hours'));$end=date('Y-m-d H:i:s',strtotime($start.' +90 minutes'));$s=db()->prepare("INSERT INTO events(owner_user_id,title,slug,subtitle,description,event_type,status,visibility,format,starts_at,ends_at,timezone,venue_name,capacity,registration_mode,is_featured) VALUES(?,?,?,?,?,?,'approved','public',?,?,?,?,?,?,'open',?)");$s->execute([$users[$i%count($users)],$title,event_slug($title),'Developer Center demo event','Generated test data for Events acceptance testing.',$types[$i%count($types)],$i%2?'physical':'virtual',$start,$end,'America/New_York',$i%2?'Hall '.($i+1):'Virtual Stage',50,$i===0?1:0]);}flash('success','Six demo events generated.');}catch(Throwable $e){flash('error',$e->getMessage());}}redirect('admin/events.php');}$events=db()->query("SELECT e.*,u.display_name owner_name,(SELECT COUNT(*) FROM event_attendees a WHERE a.event_id=e.id AND a.attendee_status<>'cancelled') registrations FROM events e JOIN users u ON u.id=e.owner_user_id ORDER BY e.created_at DESC")->fetchAll();app_header('Event Admin');?>
<section class="dashboard-hero"><p class="eyebrow">ADMINISTRATION</p><h1>Event Admin</h1><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="demo"><button class="button primary">Generate Demo Events</button></form></section><section class="form-card"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Owner</th><th>Date</th><th>Registrations</th><th>Approval</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><strong><?=e($event['title'])?></strong><br><a href="../events/manage.php?id=<?=$event['id']?>">Manage</a></td><td><?=e($event['owner_name'])?></td><td><?=e(event_date_label($event))?></td><td><?=(int)$event['registrations']?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="event_id" value="<?=$event['id']?>"><select name="status"><?php foreach(['draft','pending','approved','rejected','cancelled','completed','archived'] as $v):?><option <?=$event['status']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select><label><input type="checkbox" name="is_featured" <?=$event['is_featured']?'checked':''?>> Featured</label><button class="button ghost">Save</button></form></td></tr><?php endforeach?></tbody></table></div></section><?php app_footer();
